	private static void assertIndependentSourceRows(String body, BindingSet input, BindingSet... expectedRows) {
		String sourceQuery = "SELECT * WHERE { " + body + " }";
		List<BindingSet> sourceRows = evaluate(sourceQuery, input).stream().map(row -> merge(input, row)).toList();
		assertThat(sourceRows).as("independent source result for %s", sourceQuery)
				.containsExactlyInAnyOrder(expectedRows);
	}

	private static BindingSet row(Object... bindings) {
		MapBindingSet row = new MapBindingSet(bindings.length / 2);
		for (int index = 0; index < bindings.length; index += 2) {
			row.addBinding((String) bindings[index], (Value) bindings[index + 1]);
		}
		return row;
	}

	private static List<BindingSet> evaluate(String query) {
		return evaluate(query, EmptyBindingSet.getInstance());
	}

	private static List<BindingSet> evaluate(String query, BindingSet initialBindings) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		try (CloseableIteration<BindingSet> rows = new DefaultEvaluationStrategy(SOURCE, null).precompile(expression)
				.evaluate(initialBindings)) {
			return collect(rows);
		}
	}

	private static List<BindingSet> collect(CloseableIteration<BindingSet> rows) {
		List<BindingSet> collected = new ArrayList<>();
		while (rows.hasNext()) {
			collected.add(merge(EmptyBindingSet.getInstance(), rows.next()));
		}
		return collected;
	}

	private static BindingSet merge(BindingSet input, BindingSet row) {
		MapBindingSet merged = new MapBindingSet(input.size() + row.size());
		for (Binding binding : input) {
			merged.addBinding(binding);
		}
		for (Binding binding : row) {
			if (!merged.hasBinding(binding.getName())) {
				merged.addBinding(binding);
			}
		}
		return merged;
	}

	private record MemoryTripleSource(List<Statement> statements) implements TripleSource {
		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
